145	    if ((v = getenv("WRAPFILE_TEST_FAIL_FSYNC")) && v[0] == '1')
146	        cfg_fail_fsync = 1;
147	    if ((v = getenv("WRAPFILE_TEST_TRACE_BYTES")) && v[0] == '1')
148	        cfg_trace_bytes = 1;
149	}
150	
151	static int trace_fd(void)
152	{
153	    static int fd = -2; /* -2 = not initialised */
154	    if (fd != -2)
155	        return fd;
156	
157	    const char *path = getenv("WRAPFILE_TEST_TRACE_FILE");
158	    if (!path || !path[0]) {
159	        fd = -1;
160	        return fd;
161	    }
162	    /*
163	     * Raw openat(AT_FDCWD, ...) syscall rather than open(): going through
164	     * our own open() wrapper inside the wrapfile process would mark the
165	     * trace file as a tracked, created descriptor and mis-attribute writes
166	     * to it. The syscall bypasses all libc interposition.
167	     */
168	    fd = (int)syscall(SYS_openat, AT_FDCWD, path,
169	                      O_WRONLY | O_CREAT | O_APPEND | O_CLOEXEC, 0600);
170	    return fd;
171	}
172	
173	static void trace(const char *fmt, ...)
174	{
175	    int fd = trace_fd();
176	    if (fd < 0)
177	        return;
178	    va_list ap;
179	    va_start(ap, fmt);
180	    vdprintf(fd, fmt, ap);
181	    va_end(ap);
182	}
183	
184	/* ----- per-descriptor helpers ----- */
185	
186	static fstat_fn get_real_fstat(void)
187	{
188	    if (!real_fstat)
189	        real_fstat = (fstat_fn)dlsym(RTLD_NEXT, "fstat");
190	    return real_fstat;
191	}
192	
193	static int is_tracked(int fd)
194	{
195	    return fd >= 0 && fd < FD_MAX && tracked[fd];
196	}
197	
198	static void note_created(int fd)
199	{
200	    if (fd < 0 || fd >= FD_MAX)
201	        return;
202	    tracked[fd] = 1;
203	    written[fd] = 0;
204	    eintr_left[fd] = (cfg_write_eintr > 0 && cfg_write_eintr < 256)
205	                         ? (unsigned char)cfg_write_eintr
206	                         : 0;
207	    written_total[fd] = 0;
208	
209	    struct stat st;
210	    fstat_fn fn = get_real_fstat();
211	    if (fn && fn(fd, &st) == 0) {
212	        trace("BORN fd=%d mode=0%04o\n", fd,
213	              (unsigned)(st.st_mode & 07777));
214	    }
215	}
216	
217	/*
218	 * Shared fstat handling for tracked fds: perform the real fstat (via the
219	 * passed function), apply fault/lie policy, log the result, and tell the
220	 * caller what to return.
221	 */
222	static int handle_fstat(int fd, void *st, int is64)
223	{
224	    int rc = is64 ? real_fstat64(fd, (struct stat64 *)st)
225	                  : real_fstat(fd, (struct stat *)st);
226	
227	    if (!is_tracked(fd))
228	        return rc;
229	
230	    if (rc != 0) {
231	        trace("FSTAT ret=-1 mode=00000 size=0\n");
232	        return rc;
233	    }
234	
235	    mode_t real_mode;
236	    off_t real_size;
237	    if (is64) {
238	        struct stat64 *s = (struct stat64 *)st;
239	        real_mode = s->st_mode;
240	        real_size = s->st_size;
241	    } else {
242	        struct stat *s = (struct stat *)st;
243	        real_mode = s->st_mode;
244	        real_size = s->st_size;
245	    }
246	
247	    if (cfg_fail_fstat) {
248	        trace("FSTAT ret=-1 mode=0%04o size=%lld\n",
249	              (unsigned)(real_mode & 07777), (long long)real_size);
250	        errno = EBADF;
251	        return -1;
252	    }
253	
254	    mode_t reported = real_mode;
255	    if (cfg_lie_mode >= 0) {
256	        reported = (real_mode & ~(mode_t)07777) | (mode_t)cfg_lie_mode;
257	        if (is64)
258	            ((struct stat64 *)st)->st_mode = reported;
259	        else
260	            ((struct stat *)st)->st_mode = reported;
261	    }
262	
263	    trace("FSTAT ret=0 mode=0%04o size=%lld\n",
264	          (unsigned)(reported & 07777), (long long)real_size);
265	    return 0;
266	}
267	
268	/* ----- intercepted libc functions ----- */
269	
270	int open(const char *path, int flags, ...)
271	{
272	    if (!real_open)
273	        real_open = (open_fn)dlsym(RTLD_NEXT, "open");
274	
275	    mode_t mode = 0;
276	    if (flags & O_CREAT) {
277	        va_list ap;
278	        va_start(ap, flags);
279	        mode = va_arg(ap, mode_t);
280	        va_end(ap);
281	    }
282	
283	    int fd = real_open(path, flags, mode);
284	
285	    if (process_active() && (flags & O_CREAT)) {
286	        load_config();
287	        if (fd >= 0)
288	            note_created(fd);
289	        trace("OPEN ret=%d flags=0%o mode=0%04o\n", fd, flags,
290	              (unsigned)(mode & 07777));
291	    }
292	    return fd;
293	}
294	
295	int open64(const char *path, int flags, ...)
296	{
297	    if (!real_open64)
298	        real_open64 = (open64_fn)dlsym(RTLD_NEXT, "open64");
299	
300	    mode_t mode = 0;
301	    if (flags & O_CREAT) {
302	        va_list ap;
303	        va_start(ap, flags);
304	        mode = va_arg(ap, mode_t);
305	        va_end(ap);
306	    }
307	
308	    int fd = real_open64(path, flags, mode);
309	
310	    if (process_active() && (flags & O_CREAT)) {
311	        load_config();
312	        if (fd >= 0)
313	            note_created(fd);
314	        trace("OPEN ret=%d flags=0%o mode=0%04o\n", fd, flags,
315	              (unsigned)(mode & 07777));
316	    }
317	    return fd;
318	}
319	
320	int fchmod(int fd, mode_t mode)
321	{
322	    if (!real_fchmod)
323	        real_fchmod = (fchmod_fn)dlsym(RTLD_NEXT, "fchmod");
324	
325	    if (!process_active())
326	        return real_fchmod(fd, mode);
327	    load_config();
328	
329	    if (is_tracked(fd) && cfg_fail_fchmod) {
330	        trace("FCHMOD ret=-1 mode=0%04o\n", (unsigned)(mode & 07777));
331	        errno = EPERM;
332	        return -1;
333	    }
334	
335	    int rc = real_fchmod(fd, mode);
336	    if (is_tracked(fd)) {
337	        trace("FCHMOD ret=%d mode=0%04o\n", rc,
338	              (unsigned)(mode & 07777));
339	    }
340	    return rc;
341	}
342	
343	int fstat(int fd, struct stat *st)
344	{
345	    if (!real_fstat)
346	        real_fstat = (fstat_fn)dlsym(RTLD_NEXT, "fstat");
347	    if (!process_active())
348	        return real_fstat(fd, st);
349	    load_config();
350	    if (!is_tracked(fd))
351	        return real_fstat(fd, st);
352	    return handle_fstat(fd, st, 0);
353	}
354	
355	int fstat64(int fd, struct stat64 *st)
356	{
357	    if (!real_fstat64)
358	        real_fstat64 = (fstat64_fn)dlsym(RTLD_NEXT, "fstat64");
359	    if (!process_active())
360	        return real_fstat64(fd, st);
361	    load_config();
362	    if (!is_tracked(fd))
363	        return real_fstat64(fd, st);
364	    return handle_fstat(fd, st, 1);
365	}
366	
367	ssize_t write(int fd, const void *buf, size_t count)
368	{
369	    if (!real_write)
370	        real_write = (write_fn)dlsym(RTLD_NEXT, "write");
371	
372	    if (!process_active() || !is_tracked(fd))
373	        return real_write(fd, buf, count);
374	    load_config();
375	
376	    if (!written[fd]) {
377	        written[fd] = 1;
378	        struct stat st;
379	        fstat_fn fn = get_real_fstat();
380	        if (fn && fn(fd, &st) == 0) {
381	            trace("FIRST_WRITE mode=0%04o size=%lld\n",
382	                  (unsigned)(st.st_mode & 07777),
383	                  (long long)st.st_size);
384	        } else {
385	            trace("FIRST_WRITE mode=unknown size=unknown\n");
386	        }
387	    }
388	
389	    /* A recoverable interruption: the call fails before any byte is
390	     * consumed, and the next call succeeds. */
391	    if (eintr_left[fd] > 0) {
392	        eintr_left[fd]--;
393	        trace("WRITE ret=-1 errno=EINTR\n");
394	        errno = EINTR;
395	        return -1;
396	    }
397	
398	    /* A kernel that only accepts part of the buffer per call. */
399	    size_t allowed = count;
400	    if (cfg_partial_write > 0 && allowed > (size_t)cfg_partial_write)
401	        allowed = (size_t)cfg_partial_write;
402	
403	    /* An unrecoverable error once N bytes have landed. */
404	    if (cfg_fail_write_after >= 0) {
405	        long long remaining =
406	            (long long)cfg_fail_write_after - (long long)written_total[fd];
407	        if (remaining <= 0) {
408	            trace("WRITE ret=-1 errno=EIO off=%llu\n", written_total[fd]);
409	            errno = EIO;
410	            return -1;
411	        }
412	        if (allowed > (size_t)remaining)
413	            allowed = (size_t)remaining;
414	    }
415	
416	    ssize_t r = real_write(fd, buf, allowed);
417	    if (r > 0) {
418	        unsigned long long off = written_total[fd];
419	        written_total[fd] += (unsigned long long)r;
420	        if (cfg_trace_bytes) {
421	            char *hex = malloc((size_t)r * 2 + 1);
422	            if (hex) {
423	                static const char digits[] = "0123456789abcdef";
424	                const unsigned char *p = buf;
425	                for (ssize_t i = 0; i < r; i++) {
426	                    hex[i * 2] = digits[p[i] >> 4];
427	                    hex[i * 2 + 1] = digits[p[i] & 0xf];
428	                }
429	                hex[r * 2] = '\0';
430	                trace("WRITE off=%llu req=%zu ret=%zd hex=%s\n",
431	                      off, allowed, r, hex);
432	                free(hex);
433	            } else {
434	                trace("WRITE off=%llu req=%zu ret=%zd\n", off, allowed, r);
435	            }
436	        } else {
437	            trace("WRITE off=%llu req=%zu ret=%zd\n", off, allowed, r);
438	        }
439	    } else {
440	        trace("WRITE off=%llu req=%zu ret=%zd\n",
441	              written_total[fd], allowed, r);
442	    }
443	    return r;
444	}
445	
446	int fsync(int fd)
447	{
448	    if (!real_fsync)
449	        real_fsync = (fsync_fn)dlsym(RTLD_NEXT, "fsync");
450	
451	    if (!process_active())
452	        return real_fsync(fd);
453	    load_config();
454	
455	    if (is_tracked(fd) && cfg_fail_fsync) {
456	        trace("FSYNC ret=-1\n");
457	        errno = EIO;
458	        return -1;
459	    }
460	
461	    int rc = real_fsync(fd);
462	    if (is_tracked(fd))
463	        trace("FSYNC ret=%d\n", rc);
464	    return rc;
465	}
